    // تفسيرًا على منهج المفسرين. القاعدة تُحقن فقط عند سؤال حلم/رؤيا.
    const DREAM_RE = /حلمت|رأيت في المنام|بالمنام|في منامي|رؤيا|تفسير حلم|فسر.{0,12}حلم|dream(?:t| interpretation)/i;
