const NUM_ASK_RE = /لوح(ة|ات|تين)\s*([أا]رقام|سيار|مركب|مرور|مميز|رقم|للبيع)|[أا]رقام\s*(سيارات|سيارة|سيارتي|مركبات|مركبة|لوحات|لوحة|هواتف|هاتف|جوالات|جوال|موبايل|شرائح|شريحة|للبيع|مميز)|(?:[أا]بي|[أا]بغى|[أا]ريد|بدي|ودي)\s*[أا]رقام|رقم\s*(سيارة|سيارتي|مركبة|هاتف|جوال|موبايل)?\s*(مميز|vip)|رقم\s*(سيارة|مركبة)\s*(للبيع|لي البيع)|بليت|بلايت|number plate|license plate|plate for sale/i;
