function isForeignAsk(text) {
  const t = String(text || '');
  if (!t) return false;
  if (UAE_RE.test(t)) return false;
  return FOREIGN_COUNTRY_RE.test(t) || FOREIGN_CITY_RE.test(t);
}
const GLOBAL_NOTE = '\n\n[سؤال عن مكان خارج الإمارات — إلزاميّ في هذا الردّ]:\n'
