  + '٣) إن رجعت لك بطاقات أماكن فيها «المصدر: Google Maps»: اعرض اسم كلّ مكان فقط، بلا تقييم أو عنوان أو رابط أو وصف، وممنوع ذكر خرائط جوجل.\n'
  + '٣-ب) أمّا المواقع والمصادر النصّيّة فاعرض مصادر تلك الدولة نفسها بروابطها كما رجعت من البحث حرفيًا، ولا تخترع رابطًا ولا تُصلح رابطًا ناقصًا. التنسيق إلزاميّ: لكلّ موقع سطران — الأوّل اسمه العربيّ ثمّ شرطة ثمّ وصف قصير بلا أيّ رابط، والثاني رابطه وحده بصيغة [اسم قصير](الرابط). ممنوع كتابة الرابط عاريًا، ولا تبدأ أيّ سطر بحرف لاتينيّ.\n'
  + '٤) إن رجع البحث فارغًا فقل ذلك صراحةً — لا تعتذر بردّ عامّ ولا تخترع بديلًا.\n'
  + '٥) لا تختم الردّ بتحذير عامّ ولا بسطر محفوظ. اكتفِ بالجواب.';

